//! Handles stratification of Datalog programs

use petgraph::{algo, graphmap::DiGraphMap};
use std::collections::{HashMap, HashSet};
use std::slice::Iter;
use syn::Ident;

pub struct Strata {
    list: Vec<Vec<Ident>>,
    index: HashMap<Ident, usize>,
}

impl Strata {
    pub fn new(relations: HashSet<Ident>, dependencies: HashSet<(&Ident, &Ident)>) -> Self {
        // Build the dependency graph, where an edge `a -> b` means that the
        // relation `a` is derived from the relation `b`. Every relation is
        // added as a node, even if it does not participate in any rule.
        let mut graph: DiGraphMap<&Ident, ()> = DiGraphMap::new();
        for rel in &relations {
            graph.add_node(rel);
        }
        for &(goal, fact) in &dependencies {
            graph.add_edge(goal, fact, ());
        }

        // Each stratum is a strongly connected component of the dependency
        // graph, and `tarjan_scc` returns them in reverse topological order,
        // so a relation always comes after the relations it depends on.
        let list: Vec<Vec<Ident>> = algo::tarjan_scc(&graph)
            .into_iter()
            .map(|stratum| stratum.into_iter().cloned().collect())
            .collect();

        let mut index = HashMap::new();
        for (i, stratum) in list.iter().enumerate() {
            for rel in stratum {
                index.insert(rel.clone(), i);
            }
        }

        Self { list, index }
    }

    pub fn iter(&self) -> Iter<'_, Vec<Ident>> {
        self.list.iter()
    }

    pub fn find_relation(&self, rel: &Ident) -> usize {
        *self.index.get(rel).expect("key not found in stratum index")
    }
}

