#[cfg(test)]
mod carve_local_tests {
    use super::*;
    use proc_macro2::Span;

    fn ident(name: &str) -> Ident {
        Ident::new(name, Span::call_site())
    }

    fn build(rels: &[Ident], deps: &[(usize, usize)]) -> Strata {
        let relations: HashSet<Ident> = rels.iter().cloned().collect();
        let dependencies: HashSet<(&Ident, &Ident)> =
            deps.iter().map(|&(a, b)| (&rels[a], &rels[b])).collect();
        Strata::new(relations, dependencies)
    }

    /// Every relation shows up exactly once, and `find_relation` agrees with
    /// the position of the stratum inside `iter`.
    fn check_consistency(strata: &Strata, rels: &[Ident]) {
        let mut seen: Vec<Ident> = Vec::new();
        for (i, stratum) in strata.iter().enumerate() {
            for rel in stratum {
                assert_eq!(strata.find_relation(rel), i);
                seen.push(rel.clone());
            }
        }
        assert_eq!(seen.len(), rels.len());
        for rel in rels {
            assert!(seen.contains(rel), "missing relation {}", rel);
        }
    }

    #[test]
    fn independent_relations_each_get_a_stratum() {
        let rels = vec![ident("A"), ident("B"), ident("C")];
        let strata = build(&rels, &[]);
        assert_eq!(strata.iter().count(), 3);
        for stratum in strata.iter() {
            assert_eq!(stratum.len(), 1);
        }
        check_consistency(&strata, &rels);
    }

    #[test]
    fn empty_program_has_no_strata() {
        let strata = build(&[], &[]);
        assert_eq!(strata.iter().count(), 0);
    }

    #[test]
    fn dependencies_come_first() {
        // A is derived from B, B is derived from C.
        let rels = vec![ident("A"), ident("B"), ident("C")];
        let strata = build(&rels, &[(0, 1), (1, 2)]);
        assert_eq!(strata.iter().count(), 3);
        let a = strata.find_relation(&rels[0]);
        let b = strata.find_relation(&rels[1]);
        let c = strata.find_relation(&rels[2]);
        assert!(c < b, "{} < {}", c, b);
        assert!(b < a, "{} < {}", b, a);
        check_consistency(&strata, &rels);
    }

    #[test]
    fn mutual_recursion_shares_a_stratum() {
        // A <-> B are mutually recursive, C is derived from A.
        let rels = vec![ident("A"), ident("B"), ident("C")];
        let strata = build(&rels, &[(0, 1), (1, 0), (2, 0)]);
        assert_eq!(strata.iter().count(), 2);
        assert_eq!(
            strata.find_relation(&rels[0]),
            strata.find_relation(&rels[1])
        );
        assert!(strata.find_relation(&rels[2]) > strata.find_relation(&rels[0]));
        let recursive: Vec<&Vec<Ident>> = strata.iter().filter(|s| s.len() == 2).collect();
        assert_eq!(recursive.len(), 1);
        check_consistency(&strata, &rels);
    }

    #[test]
    fn self_recursion_stays_in_its_own_stratum() {
        let rels = vec![ident("A"), ident("B")];
        let strata = build(&rels, &[(0, 0), (0, 1)]);
        assert_eq!(strata.iter().count(), 2);
        for stratum in strata.iter() {
            assert_eq!(stratum.len(), 1);
        }
        assert!(strata.find_relation(&rels[1]) < strata.find_relation(&rels[0]));
        check_consistency(&strata, &rels);
    }

    #[test]
    fn diamond_is_reverse_topologically_ordered() {
        // D <- {B, C} <- A
        let rels = vec![ident("A"), ident("B"), ident("C"), ident("D")];
        let strata = build(&rels, &[(3, 1), (3, 2), (1, 0), (2, 0)]);
        assert_eq!(strata.iter().count(), 4);
        let a = strata.find_relation(&rels[0]);
        let b = strata.find_relation(&rels[1]);
        let c = strata.find_relation(&rels[2]);
        let d = strata.find_relation(&rels[3]);
        assert!(a < b && a < c && b < d && c < d);
        check_consistency(&strata, &rels);
    }

    #[test]
    fn spans_do_not_affect_identity() {
        // Idents compare by name only, so a dependency edge built from a
        // differently-spanned ident still refers to the same relation.
        let relations: HashSet<Ident> = vec![ident("A"), ident("B")].into_iter().collect();
        let a = Ident::new("A", Span::mixed_site());
        let b = Ident::new("B", Span::mixed_site());
        let dependencies: HashSet<(&Ident, &Ident)> = vec![(&a, &b)].into_iter().collect();
        let strata = Strata::new(relations, dependencies);
        assert_eq!(strata.iter().count(), 2);
        assert!(strata.find_relation(&b) < strata.find_relation(&a));
    }

    #[test]
    #[should_panic(expected = "key not found in stratum index")]
    fn unknown_relation_panics() {
        let rels = vec![ident("A")];
        let strata = build(&rels, &[]);
        strata.find_relation(&ident("Nope"));
    }
}
